250: // statsCommand prints paired statistics for conditions A and D from stored records.
251: func statsCommand(args []string) {
252: 	flags := flag.NewFlagSet("stats", flag.ExitOnError)
253: 	output := flags.String("output", filepath.Join("packages", "benchmarks", "results", "pilot"), "results directory")
254: 	if err := flags.Parse(args); err != nil {
255: 		os.Exit(2)
256: 	}
257: 	data, err := os.ReadFile(filepath.Join(*output, "RESULTS.json"))
258: 	if err != nil {
259: 		fmt.Fprintln(os.Stderr, err)
260: 		os.Exit(1)
261: 	}
262: 	var records []runner.RunRecord
263: 	if err := json.Unmarshal(data, &records); err != nil {
264: 		fmt.Fprintln(os.Stderr, err)
265: 		os.Exit(1)
266: 	}
267: 	type key struct{ model, task string }
268: 	pairs := make(map[key]map[string]runner.RunRecord)
269: 	for _, record := range records {
270: 		k := key{model: record.Model, task: record.TaskID}
271: 		if pairs[k] == nil {
272: 			pairs[k] = make(map[string]runner.RunRecord)
273: 		}
274: 		pairs[k][record.Condition] = record
275: 	}
276: 
277: 	metrics := []struct {
278: 		name  string
279: 		value func(runner.RunRecord) float64
280: 	}{
281: 		{"input tokens", func(r runner.RunRecord) float64 { return float64(r.Tokens.Input) }},
282: 		{"output tokens", func(r runner.RunRecord) float64 { return float64(r.Tokens.Output) }},
283: 		{"reasoning tokens", func(r runner.RunRecord) float64 { return float64(r.Tokens.Reasoning) }},
284: 		{"cache read", func(r runner.RunRecord) float64 { return float64(r.Tokens.CacheRead) }},
285: 		{"duration ms", func(r runner.RunRecord) float64 { return float64(r.DurationMS) }},
286: 		{"tool calls", func(r runner.RunRecord) float64 { return float64(r.ToolCalls) }},
287: 	}
288: 	for _, metric := range metrics {
289: 		samples := make([]stats.PairedSample, 0)
290: 		for k, byCondition := range pairs {
291: 			a, hasA := byCondition["A"]
292: 			d, hasD := byCondition["D"]
293: 			if !hasA || !hasD {
294: 				continue
295: 			}
296: 			samples = append(samples, stats.PairedSample{
297: 				ID: k.model + "/" + k.task,
298: 				A:  metric.value(a),
299: 				B:  metric.value(d),
300: 			})
301: 		}
302: 		result := stats.Paired(samples)
303: 		fmt.Printf("%-18s n=%d meanA=%10.2f meanD=%10.2f diff=%10.2f CI=[%10.2f, %10.2f] p=%.4f d=%.3f\n",
304: 			metric.name, result.N, result.MeanA, result.MeanB, result.MeanDiff,
305: 			result.CILow, result.CIHigh, result.PApprox, result.CohensD)
306: 	}
307: }
