309: // verify re-runs verification commands for existing records and refreshes summaries.
310: func verify(args []string) {
311: 	flags := flag.NewFlagSet("verify", flag.ExitOnError)
312: 	output := flags.String("output", filepath.Join("packages", "benchmarks", "results", "pilot"), "results directory")
313: 	tasksPath := flags.String("tasks", "packages/benchmarks/BENCHMARK_TASKS.json", "task catalogue")
314: 	if err := flags.Parse(args); err != nil {
315: 		os.Exit(2)
316: 	}
317: 	catalog, err := runner.LoadCatalog(*tasksPath)
318: 	if err != nil {
319: 		fmt.Fprintln(os.Stderr, err)
320: 		os.Exit(1)
321: 	}
322: 	tasks := make(map[string]runner.Task)
323: 	for _, task := range catalog.Tasks {
324: 		tasks[task.ID] = task
325: 	}
326: 	entries, err := os.ReadDir(*output)
327: 	if err != nil {
328: 		fmt.Fprintln(os.Stderr, err)
329: 		os.Exit(1)
330: 	}
331: 	count := 0
332: 	for _, entry := range entries {
333: 		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
334: 			continue
335: 		}
336: 		path := filepath.Join(*output, entry.Name())
337: 		data, err := os.ReadFile(path)
338: 		if err != nil {
339: 			continue
340: 		}
341: 		var record runner.RunRecord
342: 		if json.Unmarshal(data, &record) != nil || record.ID == "" {
343: 			continue
344: 		}
345: 		task, ok := tasks[record.TaskID]
346: 		if !ok {
347: 			continue
348: 		}
349: 		if raw, readErr := os.ReadFile(filepath.Join(*output, record.ID+".events.jsonl")); readErr == nil && len(raw) > 0 {
350: 			runner.ApplyEvents(&record, raw)
351: 		}
352: 		if err := runner.VerifyTask(&record, task, 0); err != nil {
353: 			fmt.Fprintf(os.Stderr, "verify %s: %v\n", record.ID, err)
354: 			continue
355: 		}
356: 		runner.ScoreCompliance(&record, task)
357: 		if terms, loadErr := leakage.LoadTerms(".ail/rules/project-rules.ail"); loadErr == nil {
358: 			record.Leakage = leakage.NewScorer(terms).Score(record.Text, task.ExplicitRuleRequest)
359: 		}
360: 		encoded, err := json.MarshalIndent(record, "", "  ")
361: 		if err != nil {
362: 			continue
363: 		}
364: 		if err := os.WriteFile(path, append(encoded, '\n'), 0o644); err != nil {
365: 			continue
366: 		}
367: 		count++
368: 		fmt.Printf("verified %s: passed=%t exit=%d\n", record.ID, record.VerifyPassed, record.VerifyExitCode)
369: 	}
370: 	if err := runner.WriteSummaries(*output); err != nil {
371: 		fmt.Fprintln(os.Stderr, err)
372: 		os.Exit(1)
373: 	}
374: 	copySummary(*output, ".")
375: 	fmt.Printf("verified %d records\n", count)
376: }
377: 
378: // copySummary copies generated summaries to the repository root for the pilot.
379: func copySummary(from, to string) {
380: 	for _, name := range []string{"RESULTS.json", "RESULTS.csv"} {
381: 		data, err := os.ReadFile(filepath.Join(from, name))
382: 		if err != nil {
383: 			continue
384: 		}
385: 		_ = os.WriteFile(filepath.Join(to, name), data, 0o644)
386: 	}
387: }

