176: 		payload, err := runner.InstructionPayload(item.Format, item.Delimiters)
177: 		if err != nil {
178: 			fmt.Fprintln(os.Stderr, err)
179: 			os.Exit(1)
180: 		}
181: 		payloads[item.Name] = payload
182: 	}
183: 
184: 	planned := len(models) * len(activeConditions) * len(tasks)
185: 	completed := 0
186: 	failed := 0
187: 	for _, model := range models {
188: 		for _, item := range activeConditions {
189: 			for _, task := range tasks {
190: 				request := runner.Request{
191: 					Task:           task,
192: 					Model:          model,
193: 					Format:         item.Format,
194: 					Delimiters:     item.Delimiters,
195: 					Condition:      item.Name,
196: 					Instruction:    payloads[item.Name],
197: 					WorkspaceRoot:  workspaceRoot,
198: 					OutputDir:      outputDir,
199: 					Timeout:        0,
200: 					OpenCodeBinary: *binary,
201: 				}
202: 				record, err := runner.RunOne(request)
203: 				if err != nil {
204: 					fmt.Fprintf(os.Stderr, "run %s failed: %v\n", task.ID, err)
205: 					failed++
206: 					continue
207: 				}
208: 				completed++
209: 				fmt.Printf("[%d/%d] %s %s %s success=%t tokens=%d/%d ms=%d\n",
210: 					completed, planned, item.Name, model.Label, task.ID,
211: 					record.Success, record.Tokens.Input, record.Tokens.Output, record.DurationMS)
212: 			}
213: 		}
214: 	}
