216: 	if err := runner.WriteSummaries(outputDir); err != nil {
217: 		fmt.Fprintln(os.Stderr, err)
218: 		os.Exit(1)
219: 	}
220: 	if *mode == "pilot" {
221: 		copySummary(outputDir, ".")
222: 	}
