406: // RunOne executes a single task and persists its record. Completed successful runs are skipped.
407: func RunOne(request Request) (RunRecord, error) {
408: 	if err := os.MkdirAll(request.OutputDir, 0o755); err != nil {
409: 		return RunRecord{}, err
410: 	}
411: 	id := fmt.Sprintf("%s__%s__%s__%s", request.Condition, request.Task.ID, sanitize(request.Model.ID), request.Format)
412: 	recordPath := filepath.Join(request.OutputDir, id+".json")
413: 	if existing, err := os.ReadFile(recordPath); err == nil {
414: 		var record RunRecord
415: 		if json.Unmarshal(existing, &record) == nil && record.Success {
416: 			return record, nil
417: 		}
418: 	}
419: 
420: 	workDir, err := prepareWorkspace(request.WorkspaceRoot, id, request.Task)
421: 	if err != nil {
422: 		return RunRecord{}, err
423: 	}
424: 	binary := request.OpenCodeBinary
425: 	if binary == "" {
426: 		binary = "opencode"
427: 	}
428: 	prompt := request.Instruction + "\n\n--- TASK ---\n\n" + request.Task.Prompt
429: 	promptPath := filepath.Join(workDir, "prompt.md")
430: 	if err := os.WriteFile(promptPath, []byte(prompt), 0o644); err != nil {
431: 		return RunRecord{}, err
432: 	}
433: 
434: 	timeout := request.Timeout
435: 	if timeout <= 0 {
436: 		timeout = 10 * time.Minute
437: 	}
438: 	ctx, cancel := context.WithTimeout(context.Background(), timeout)
439: 	defer cancel()
440: 
441: 	args := []string{
442: 		"run",
443: 		"--model", request.Model.ID,
444: 		"--format", "json",
445: 		"--auto",
446: 		"--archived",
447: 		"--title", "ail-bench-"+id,
448: 		"--file", "prompt.md",
449: 		"Execute the task described in the attached file.",
450: 	}
451: 	cmd := exec.CommandContext(ctx, binary, args...)
452: 	cmd.Dir = workDir
453: 	var stdout, stderr bytes.Buffer
454: 	cmd.Stdout = &stdout
455: 	cmd.Stderr = &stderr
456: 
457: 	record := RunRecord{
458: 		ID:         id,
459: 		TaskID:     request.Task.ID,
460: 		Category:   request.Task.Category,
461: 		Model:      request.Model.ID,
462: 		Format:     request.Format,
463: 		Delimiters: request.Delimiters,
464: 		Condition:  request.Condition,
465: 		StartedAt:  time.Now().UTC(),
466: 		WorkDir:    workDir,
467: 	}
468: 	runErr := cmd.Run()
469: 	record.FinishedAt = time.Now().UTC()
470: 	record.DurationMS = record.FinishedAt.Sub(record.StartedAt).Milliseconds()
471: 	if runErr != nil {
472: 		record.Error = runErr.Error()
473: 		if stderr.Len() > 0 {
474: 			record.Error += ": " + stderr.String()
475: 		}
476: 	}
477: 	if exitError, ok := runErr.(*exec.ExitError); ok {
478: 		record.ExitCode = exitError.ExitCode()
479: 	}
480: 
481: 	ApplyEvents(&record, stdout.Bytes())
482: 	if runErr != nil {
483: 		record.Success = false
484: 	}
485: 	if terms, loadErr := leakage.LoadTerms(".ail/rules/project-rules.ail"); loadErr == nil {
486: 		record.Leakage = leakage.NewScorer(terms).Score(record.Text, request.Task.ExplicitRuleRequest)
487: 	}
488: 	if err := VerifyTask(&record, request.Task, 0); err != nil {
489: 		record.VerifyOutput = fmt.Sprintf("verification error: %v", err)
490: 	}
491: 	ScoreCompliance(&record, request.Task)
492: 
493: 	rawPath := filepath.Join(request.OutputDir, id+".events.jsonl")
494: 	if err := os.WriteFile(rawPath, stdout.Bytes(), 0o644); err != nil {
495: 		return record, err
496: 	}
497: 	encoded, err := json.MarshalIndent(record, "", "  ")
498: 	if err != nil {
499: 		return record, err
500: 	}
501: 	if err := os.WriteFile(recordPath, append(encoded, '\n'), 0o644); err != nil {
502: 		return record, err
503: 	}
504: 	return record, nil
505: }
