224: func parseEvents(raw []byte) (text string, tokens Tokens, cost float64, sessionID string, toolCalls, eventCount int) {
225: 	scanner := bufio.NewScanner(bytes.NewReader(raw))
226: 	scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)
227: 	var builder strings.Builder
228: 	var accumulated Tokens
229: 	var accumulatedCost float64
230: 	for scanner.Scan() {
231: 		line := bytes.TrimSpace(scanner.Bytes())
232: 		if len(line) == 0 {
233: 			continue
234: 		}
235: 		var item event
236: 		if err := json.Unmarshal(line, &item); err != nil {
237: 			continue
238: 		}
239: 		eventCount++
240: 		if item.SessionID != "" {
241: 			sessionID = item.SessionID
242: 		}
243: 		var part map[string]json.RawMessage
244: 		if err := json.Unmarshal(item.Part, &part); err != nil {
245: 			continue
246: 		}
247: 		if typeRaw, ok := part["type"]; ok {
248: 			var partType string
249: 			_ = json.Unmarshal(typeRaw, &partType)
250: 			if strings.HasPrefix(partType, "tool") {
251: 				toolCalls++
252: 			}
253: 		}
254: 		if item.Type == "text" {
255: 			if textRaw, ok := part["text"]; ok {
256: 				var chunk string
257: 				if json.Unmarshal(textRaw, &chunk) == nil {
258: 					builder.WriteString(chunk)
259: 				}
260: 			}
261: 		}
262: 		if item.Type == "step_finish" {
263: 			var finish finishPart
264: 			if json.Unmarshal(item.Part, &finish) == nil {
265: 				accumulated.Input += finish.Tokens.Input
266: 				accumulated.Output += finish.Tokens.Output
267: 				accumulated.Reasoning += finish.Tokens.Reasoning
268: 				accumulated.CacheRead += finish.Tokens.Cache.Read
269: 				accumulated.CacheWrite += finish.Tokens.Cache.Write
270: 				accumulatedCost += finish.Cost
271: 			}
272: 		}
273: 	}
274: 	return builder.String(), accumulated, accumulatedCost, sessionID, toolCalls, eventCount
275: }
