317: // ScoreCompliance evaluates the machine-checkable applicable rules in a workspace.
318: func ScoreCompliance(record *RunRecord, task Task) {
319: 	result := Compliance{Applicable: len(task.ApplicableRules), Violated: []string{}}
320: 	machineRules := map[string]bool{"R001": true, "R002": true, "R003": true}
321: 	for _, rule := range task.ApplicableRules {
322: 		if !machineRules[rule] {
323: 			continue
324: 		}
325: 		result.Checked++
326: 		passed := false
327: 		switch rule {
328: 		case "R001":
329: 			passed = !workspaceContainsDash(record.WorkDir)
330: 		case "R002":
331: 			passed = !workspaceHasLargeFile(record.WorkDir)
332: 		case "R003":
333: 			passed = record.VerifyPassed
334: 		}
335: 		if passed {
336: 			result.Followed++
337: 		} else {
338: 			result.Violated = append(result.Violated, rule)
339: 		}
340: 	}
341: 	if result.Checked > 0 {
342: 		result.Pct = float64(result.Followed) / float64(result.Checked) * 100
343: 	}
344: 	record.Compliance = result
345: }
346: 
347: func workspaceContainsDash(root string) bool {
348: 	found := false
349: 	_ = filepath.WalkDir(root, func(path string, entry os.DirEntry, err error) error {
350: 		if err != nil || entry.IsDir() {
351: 			return nil
352: 		}
353: 		data, err := os.ReadFile(path)
354: 		if err != nil || len(data) > 1<<20 {
355: 			return nil
356: 		}
357: 		if strings.Contains(string(data), "\u2014") {
358: 			found = true
359: 		}
360: 		return nil
361: 	})
362: 	return found
363: }
364: 
365: func workspaceHasLargeFile(root string) bool {
366: 	found := false
367: 	_ = filepath.WalkDir(root, func(path string, entry os.DirEntry, err error) error {
368: 		if err != nil || entry.IsDir() {
369: 			return nil
370: 		}
371: 		data, err := os.ReadFile(path)
372: 		if err != nil || len(data) > 1<<20 {
373: 			return nil
374: 		}
375: 		if strings.Count(string(data), "\n")+1 > 700 {
376: 			found = true
377: 		}
378: 		return nil
379: 	})
380: 	return found
381: }
