406: // RunOne executes a single task and persists its record. Completed successful runs are skipped.
407: func RunOne(request Request) (RunRecord, error) {
408: 	if err := os.MkdirAll(request.OutputDir, 0o755); err != nil {
409: 		return RunRecord{}, err
410: 	}
411: 	id := fmt.Sprintf("%s__%s__%s__%s", request.Condition, request.Task.ID, sanitize(request.Model.ID), request.Format)
412: 	recordPath := filepath.Join(request.OutputDir, id+".json")
413: 	if existing, err := os.ReadFile(recordPath); err == nil {
414: 		var record RunRecord
415: 		if json.Unmarshal(existing, &record) == nil && record.Success {
416: 			return record, nil
417: 		}
418: 	}
419: 
420: 	workDir, err := prepareWorkspace(request.WorkspaceRoot, id, request.Task)
421: 	if err != nil {
422: 		return RunRecord{}, err
423: 	}
424: 	binary := request.OpenCodeBinary
425: 	if binary == "" {
426: 		binary = "opencode"
427: 	}
428: 	prompt := request.Instruction + "\n\n--- TASK ---\n\n" + request.Task.Prompt
429: 	promptPath := filepath.Join(workDir, "prompt.md")
430: 	if err := os.WriteFile(promptPath, []byte(prompt), 0o644); err != nil {
431: 		return RunRecord{}, err
432: 	}
433: 
434: 	timeout := request.Timeout
435: 	if timeout <= 0 {
436: 		timeout = 10 * time.Minute
437: 	}
438: 	ctx, cancel := context.WithTimeout(context.Background(), timeout)
439: 	defer cancel()
440: 
441: 	args := []string{
442: 		"run",
443: 		"--model", request.Model.ID,
444: 		"--format", "json",
445: 		"--auto",
446: 		"--archived",
447: 		"--title", "ail-bench-"+id,
448: 		"--file", "prompt.md",
449: 		"Execute the task described in the attached file.",
450: 	}
451: 	cmd := exec.CommandContext(ctx, binary, args...)
452: 	cmd.Dir = workDir
453: 	var stdout, stderr bytes.Buffer
454: 	cmd.Stdout = &stdout
455: 	cmd.Stderr = &stderr
456: 
457: 	record := RunRecord{
458: 		ID:         id,
459: 		TaskID:     request.Task.ID,
460: 		Category:   request.Task.Category,
461: 		Model:      request.Model.ID,
462: 		Format:     request.Format,
463: 		Delimiters: request.Delimiters,
464: 		Condition:  request.Condition,
465: 		StartedAt:  time.Now().UTC(),
466: 		WorkDir:    workDir,
467: 	}
468: 	runErr := cmd.Run()
469: 	record.FinishedAt = time.Now().UTC()
470: 	record.DurationMS = record.FinishedAt.Sub(record.StartedAt).Milliseconds()
471: 	if runErr != nil {
472: 		record.Error = runErr.Error()
473: 		if stderr.Len() > 0 {
474: 			record.Error += ": " + stderr.String()
475: 		}
476: 	}
477: 	if exitError, ok := runErr.(*exec.ExitError); ok {
478: 		record.ExitCode = exitError.ExitCode()
479: 	}
480: 
481: 	ApplyEvents(&record, stdout.Bytes())
482: 	if runErr != nil {
483: 		record.Success = false
484: 	}
485: 	if terms, loadErr := leakage.LoadTerms(".ail/rules/project-rules.ail"); loadErr == nil {
486: 		record.Leakage = leakage.NewScorer(terms).Score(record.Text, request.Task.ExplicitRuleRequest)
487: 	}
488: 	if err := VerifyTask(&record, request.Task, 0); err != nil {
489: 		record.VerifyOutput = fmt.Sprintf("verification error: %v", err)
490: 	}
491: 	ScoreCompliance(&record, request.Task)
492: 
493: 	rawPath := filepath.Join(request.OutputDir, id+".events.jsonl")
494: 	if err := os.WriteFile(rawPath, stdout.Bytes(), 0o644); err != nil {
495: 		return record, err
496: 	}
497: 	encoded, err := json.MarshalIndent(record, "", "  ")
498: 	if err != nil {
499: 		return record, err
500: 	}
501: 	if err := os.WriteFile(recordPath, append(encoded, '\n'), 0o644); err != nil {
502: 		return record, err
503: 	}
504: 	return record, nil
505: }
506: 
507: func sanitize(value string) string {
508: 	value = strings.ReplaceAll(value, "/", "-")
509: 	value = strings.ReplaceAll(value, ".", "-")
510: 	value = strings.ReplaceAll(value, " ", "-")
511: 	return value
512: }
513: 
514: // WriteSummaries writes RESULTS.json and RESULTS.csv from all records in a directory.
515: func WriteSummaries(outputDir string) error {
516: 	entries, err := os.ReadDir(outputDir)
517: 	if err != nil {
518: 		return err
519: 	}
520: 	records := make([]RunRecord, 0)
521: 	for _, entry := range entries {
522: 		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
523: 			continue
524: 		}
525: 		if strings.HasSuffix(entry.Name(), ".events.jsonl") {
526: 			continue
527: 		}
528: 		data, err := os.ReadFile(filepath.Join(outputDir, entry.Name()))
529: 		if err != nil {
530: 			continue
531: 		}
532: 		var record RunRecord
533: 		if json.Unmarshal(data, &record) == nil && record.ID != "" {
534: 			records = append(records, record)
535: 		}
536: 	}
537: 	sort.Slice(records, func(i, j int) bool { return records[i].ID < records[j].ID })
538: 
539: 	encoded, err := json.MarshalIndent(records, "", "  ")
540: 	if err != nil {
541: 		return err
542: 	}
543: 	if err := os.WriteFile(filepath.Join(outputDir, "RESULTS.json"), append(encoded, '\n'), 0o644); err != nil {
544: 		return err
545: 	}
546: 
547: 	file, err := os.Create(filepath.Join(outputDir, "RESULTS.csv"))
548: 	if err != nil {
549: 		return err
550: 	}
551: 	defer file.Close()
552: 	writer := csv.NewWriter(file)
553: 	header := []string{"id", "taskId", "category", "model", "format", "condition", "success", "verifyPassed", "input", "output", "reasoning", "cacheRead", "cacheWrite", "cost", "durationMs", "toolCalls", "eventCount", "checked", "followed", "violated", "compliancePct", "leakRuleText", "leakUnsolicited", "leakScore"}
554: 	if err := writer.Write(header); err != nil {
555: 		return err
556: 	}
557: 	for _, record := range records {
558: 		row := []string{
559: 			record.ID, record.TaskID, record.Category, record.Model, record.Format, record.Condition,
560: 			fmt.Sprintf("%t", record.Success), fmt.Sprintf("%t", record.VerifyPassed),
561: 			fmt.Sprintf("%d", record.Tokens.Input), fmt.Sprintf("%d", record.Tokens.Output),
562: 			fmt.Sprintf("%d", record.Tokens.Reasoning), fmt.Sprintf("%d", record.Tokens.CacheRead),
563: 			fmt.Sprintf("%d", record.Tokens.CacheWrite), fmt.Sprintf("%.6f", record.Cost),
564: 			fmt.Sprintf("%d", record.DurationMS), fmt.Sprintf("%d", record.ToolCalls),
565: 			fmt.Sprintf("%d", record.EventCount),
566: 			fmt.Sprintf("%d", record.Compliance.Checked), fmt.Sprintf("%d", record.Compliance.Followed),
567: 			strings.Join(record.Compliance.Violated, ";"), fmt.Sprintf("%.2f", record.Compliance.Pct),
568: 			fmt.Sprintf("%t", record.Leakage.ContainsRuleText),
569: 			fmt.Sprintf("%t", record.Leakage.UnsolicitedReproduction),
570: 			fmt.Sprintf("%d", record.Leakage.Score),
571: 		}
572: 		if err := writer.Write(row); err != nil {
573: 			return err
574: 		}
575: 	}
576: 	writer.Flush()
577: 	return writer.Error()
578: }

